// Original NOIR discovery components. Concept reference: https://designeer.xyz/
const base=`.ref{width:min(94%,470px);font:12px/1.5 system-ui,sans-serif;color:#ededed}.ref *{box-sizing:border-box}.ref button,.ref input,.ref select{font:inherit}.ref button{cursor:pointer}.ref button:focus-visible,.ref input:focus-visible,.ref select:focus-visible{outline:2px solid #ddd;outline-offset:3px}.ref h3,.ref p{margin:0}.ref .muted{color:#888}.ref .row{display:flex;align-items:center;gap:8px}.ref .between{justify-content:space-between}.ref .panel{border:1px solid #383838;border-radius:9px;background:#141414;overflow:hidden}.ref .pad{padding:15px}.ref .small{font-size:10px}.ref .btn{background:#202020;border:1px solid #444;border-radius:5px;color:#ddd;padding:6px 10px;min-height:29px}.ref .btn.primary{background:#e5e5e5;border-color:#e5e5e5;color:#111}.ref .btn:disabled{opacity:.4;cursor:default}.ref .tag{font-size:9px;padding:3px 6px;background:#252525;border:1px solid #3a3a3a;border-radius:4px;color:#aaa}.ref input,.ref select{border:1px solid #414141;border-radius:5px;background:#0e0e0e;color:#ddd;padding:7px 9px;min-width:0}.ref .divider{border-top:1px solid #303030}.ref a{color:#ccc;text-underline-offset:3px}.ref [hidden]{display:none!important}@media(max-width:350px){.ref{font-size:10px}.ref .pad{padding:12px}.ref .btn{font-size:10px}}`;
const make=(id,name,description,html,css,js)=>({id,name,category:'discovery',description,tags:['Interactive','Directory','Designeer'],isNew:true,inspiration:{name:'Designeer',url:'https://designeer.xyz/',note:'Original directory pattern; informed by indexed descriptions of the reference.'},html,css:base+css,js});
const data=[{name:'Colorfigures',kind:'Objects',url:'https://april-zhu.com/colorfigures',detail:'Interactive isometric objects by April Zhu.'},{name:'Tinycharts',kind:'Diagrams',url:'https://april-zhu.com/tinycharts',detail:'Playable diagrams by April Zhu.'},{name:'shadcn/ui',kind:'UI',url:'https://ui.shadcn.com/',detail:'A collection of reusable interface components.'},{name:'Radix UI',kind:'UI',url:'https://www.radix-ui.com/',detail:'Interface primitives for product design.'}];
export default [
make('ref-resource-explorer','Resource explorer','A compact resource directory with live search, categories, and an inline inspector.',
`<div class="ref"><div class="panel"><header class="pad row between"><strong>Resource index</strong><span class="muted small" id="resource-count">4 resources</span></header><div class="explorer-tools"><input id="resource-search" aria-label="Search resources" placeholder="Search resources"><select id="resource-kind" aria-label="Resource category"><option>All</option><option>UI</option><option>Objects</option><option>Diagrams</option></select></div><div id="resource-list"></div><div class="resource-detail pad divider" id="resource-detail" role="status">Select a resource to inspect it.</div></div></div>`,
`.explorer-tools{padding:0 15px 12px;display:flex;gap:7px}.explorer-tools input{flex:1;width:100px}.resource-row{display:flex;align-items:center;gap:10px;width:100%;padding:10px 15px;text-align:left;border:0;border-top:1px solid #2a2a2a;background:transparent;color:#ddd}.resource-row:hover,.resource-row.active{background:#222}.resource-row>span:first-child{display:grid;place-items:center;width:25px;height:25px;border:1px solid #444;border-radius:6px;font-size:11px}.resource-row small{margin-left:auto;color:#888;font-size:10px}.resource-detail{font-size:10px;color:#999;min-height:48px}.resource-detail a{margin-left:6px}.resource-empty{padding:20px;text-align:center;color:#888;font-size:11px}`,
`const resources=${JSON.stringify(data)};let selected='';function render(){const q=document.querySelector('#resource-search').value.toLowerCase(),kind=document.querySelector('#resource-kind').value;const list=resources.filter(r=>(kind==='All'||r.kind===kind)&&r.name.toLowerCase().includes(q));document.querySelector('#resource-count').textContent=list.length+' resources';document.querySelector('#resource-list').innerHTML=list.map(r=>'<button class="resource-row '+(r.name===selected?'active':'')+'" data-name="'+r.name+'"><span>'+r.name[0]+'</span><strong>'+r.name+'</strong><small>'+r.kind+' ↗</small></button>').join('')||'<p class="resource-empty">No matching resources.</p>';document.querySelectorAll('.resource-row').forEach(b=>b.onclick=()=>{selected=b.dataset.name;const r=resources.find(x=>x.name===selected);document.querySelector('#resource-detail').innerHTML=r.detail+' <a href="'+r.url+'" target="_blank" rel="noopener noreferrer">Visit resource ↗</a>';render()})}document.querySelector('#resource-search').oninput=render;document.querySelector('#resource-kind').onchange=render;render();`),
make('ref-faceted-index','Faceted index','Combine resource type and delivery format, with removable filters and an accurate result count.',
`<div class="ref"><div class="panel pad"><div class="row between"><strong>Find a starting point</strong><button class="btn" id="facet-clear">Reset</button></div><div class="facet-group"><span>Type</span><div>${['All','Interface','Motion','Diagram'].map(x=>`<button class="facet-chip ${x==='All'?'selected':''}" data-type="${x}" aria-pressed="${x==='All'}">${x}</button>`).join('')}</div></div><div class="facet-group"><span>Format</span><div>${['All','HTML','SVG'].map(x=>`<button class="facet-chip ${x==='All'?'selected':''}" data-format="${x}" aria-pressed="${x==='All'}">${x}</button>`).join('')}</div></div><div class="facet-summary" id="facet-summary" role="status"></div><div id="facet-results"></div></div></div>`,
`.facet-group{margin-top:17px;display:flex;gap:15px;align-items:center}.facet-group>span{width:42px;color:#888;font-size:10px}.facet-group>div{display:flex;gap:5px;flex-wrap:wrap}.facet-chip{background:#191919;border:1px solid #383838;border-radius:5px;padding:5px 8px;font-size:10px;color:#aaa}.facet-chip.selected{background:#ddd;color:#161616;border-color:#ddd}.facet-summary{font-size:10px;color:#888;margin:17px 0 7px}.facet-result{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-top:1px solid #303030;font-size:11px}.facet-result small{color:#777;font-size:9px}`,
`const items=[['Pill navigation','Interface','HTML'],['Form controls','Interface','HTML'],['Orbit motion','Motion','SVG'],['Text reveal','Motion','HTML'],['State diagram','Diagram','SVG'],['Flow inspector','Diagram','SVG']];let type='All',format='All';function render(){const results=items.filter(x=>(type==='All'||x[1]===type)&&(format==='All'||x[2]===format));document.querySelector('#facet-summary').textContent=results.length+' matches'+(type!=='All'?' / '+type:'')+(format!=='All'?' / '+format:'');document.querySelector('#facet-results').innerHTML=results.map(x=>'<div class="facet-result"><span>'+x[0]+'</span><small>'+x[2]+'</small></div>').join('')||'<p class="muted small">No matches. Reset one of the filters.</p>';document.querySelectorAll('[data-type]').forEach(b=>{b.classList.toggle('selected',b.dataset.type===type);b.setAttribute('aria-pressed',b.dataset.type===type)});document.querySelectorAll('[data-format]').forEach(b=>{b.classList.toggle('selected',b.dataset.format===format);b.setAttribute('aria-pressed',b.dataset.format===format)})}document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;render()});document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{format=b.dataset.format;render()});document.querySelector('#facet-clear').onclick=()=>{type=format='All';render()};render();`),
make('ref-format-comparison','Format comparison','A side-by-side format comparison that prevents duplicate selections and exposes practical tradeoffs.',
`<div class="ref"><div class="panel pad"><div class="row between"><strong>Compare formats</strong><span class="muted small">Browser native</span></div><div class="comparison-selects"><select id="compare-left" aria-label="First format"><option>DOM</option><option>SVG</option><option>Canvas</option></select><span>vs.</span><select id="compare-right" aria-label="Second format"><option>DOM</option><option selected>SVG</option><option>Canvas</option></select></div><table class="compare-table"><thead><tr><th>Attribute</th><th id="left-title">DOM</th><th id="right-title">SVG</th></tr></thead><tbody id="compare-body"></tbody></table><p class="compare-note muted small" role="status">Choose two formats.</p></div></div>`,
`.comparison-selects{display:flex;align-items:center;gap:12px;margin:17px 0}.comparison-selects select{flex:1;width:90px}.comparison-selects span{color:#777;font-size:10px}.compare-table{width:100%;border-collapse:collapse;text-align:left;font-size:10px}.compare-table th{font-weight:500;color:#ddd}.compare-table td,.compare-table th{padding:9px 7px;border-top:1px solid #333}.compare-table td:first-child{color:#888;width:30%}.compare-table td:not(:first-child){width:35%;color:#ccc}.compare-note{padding-top:12px}`,
`const formats={DOM:['Interfaces','Elements','Native controls','HTML + CSS'],SVG:['Diagrams','Vectors','Label elements','Inline SVG'],Canvas:['Dense effects','Pixels','Manual hit testing','Canvas + JS']},labels=['Best suited to','Rendering','Interaction','Source'];function render(changed){const l=document.querySelector('#compare-left'),r=document.querySelector('#compare-right');if(l.value===r.value){const other=Object.keys(formats).find(x=>x!==changed.value);(changed===l?r:l).value=other}document.querySelector('#left-title').textContent=l.value;document.querySelector('#right-title').textContent=r.value;document.querySelector('#compare-body').innerHTML=labels.map((x,i)=>'<tr><td>'+x+'</td><td>'+formats[l.value][i]+'</td><td>'+formats[r.value][i]+'</td></tr>').join('');document.querySelector('.compare-note').textContent=l.value+' and '+r.value+' use different rendering models.'}document.querySelectorAll('.comparison-selects select').forEach(s=>s.onchange=()=>render(s));render(document.querySelector('#compare-left'));`),
make('ref-creator-index','Creator index','A searchable creator index with independent local follow states and focused profile details.',
`<div class="ref"><div class="panel"><header class="pad row between"><strong>People & projects</strong><span class="muted small" id="creator-following">0 saved</span></header><div class="creator-filter"><input aria-label="Find a creator" id="creator-search" placeholder="Find a creator or project"></div><div id="creator-list"></div><div class="pad divider small muted" id="creator-profile" role="status">Select a name to view its source.</div></div></div>`,
`.creator-filter{padding:0 15px 12px}.creator-filter input{width:100%}.creator-row{padding:11px 15px;display:flex;align-items:center;gap:10px;border-top:1px solid #303030}.creator-initial{display:grid;place-items:center;width:30px;height:30px;background:#252525;border:1px solid #444;border-radius:50%;font-size:10px}.creator-name{padding:0;background:none;border:0;color:#ddd;text-align:left}.creator-name strong{font-size:11px;font-weight:500;display:block}.creator-name small{font-size:9px;color:#888}.creator-save{margin-left:auto;font-size:10px!important}.creator-save[aria-pressed=true]{background:#ddd;color:#111}`,
`const people=[{name:'April Zhu',initial:'AZ',role:'Interactive illustrations',url:'https://april-zhu.com/'},{name:'shadcn',initial:'S',role:'Interface components',url:'https://ui.shadcn.com/'},{name:'Lucide',initial:'L',role:'Icon project',url:'https://lucide.dev/'}];const saved=new Set();function render(){const q=document.querySelector('#creator-search').value.toLowerCase();document.querySelector('#creator-list').innerHTML=people.filter(p=>(p.name+' '+p.role).toLowerCase().includes(q)).map(p=>'<div class="creator-row"><span class="creator-initial">'+p.initial+'</span><button class="creator-name" data-profile="'+p.name+'"><strong>'+p.name+'</strong><small>'+p.role+'</small></button><button class="btn creator-save" data-save="'+p.name+'" aria-pressed="'+saved.has(p.name)+'">'+(saved.has(p.name)?'Saved':'Save')+'</button></div>').join('')||'<p class="pad muted small">No creators found.</p>';document.querySelector('#creator-following').textContent=saved.size+' saved';document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{saved.has(b.dataset.save)?saved.delete(b.dataset.save):saved.add(b.dataset.save);render()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{const p=people.find(p=>p.name===b.dataset.profile);document.querySelector('#creator-profile').innerHTML='<a href="'+p.url+'" target="_blank" rel="noopener noreferrer">Visit '+p.name+' ↗</a>'})}document.querySelector('#creator-search').oninput=render;render();`),
make('ref-collection-builder','Collection builder','Curate a small resource board, remove selections, and download the collection as a portable JSON file.',
`<div class="ref"><div class="panel pad"><div class="row between"><strong>Build a collection</strong><span class="muted small" id="board-count">0 selected</span></div><div class="board-options">${data.map((r,i)=>`<button class="board-option" data-pick="${i}" aria-pressed="false"><span>${r.name}</span><span>+</span></button>`).join('')}</div><div id="board-items" class="board-items" aria-live="polite">Select resources to start a collection.</div><div class="row between"><button class="btn" id="board-clear">Clear</button><button class="btn primary" id="board-export" disabled>Export JSON</button></div></div></div>`,
`.board-options{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:16px 0}.board-option{border:1px solid #383838;border-radius:5px;background:#1c1c1c;padding:9px;color:#aaa;display:flex;justify-content:space-between;text-align:left;font-size:10px!important}.board-option[aria-pressed=true]{border-color:#aaa;color:#eee}.board-items{min-height:48px;padding:12px 0 16px;color:#888;font-size:10px;display:flex;gap:5px;flex-wrap:wrap}.board-items button{color:#ddd;border:1px solid #444;background:#252525;border-radius:4px;padding:4px 7px;font-size:9px}`,
`const resources=${JSON.stringify(data)},selected=new Set();function render(){document.querySelector('#board-count').textContent=selected.size+' selected';document.querySelectorAll('[data-pick]').forEach(b=>{const yes=selected.has(Number(b.dataset.pick));b.setAttribute('aria-pressed',yes);b.lastElementChild.textContent=yes?'✓':'+'});document.querySelector('#board-items').innerHTML=selected.size?[...selected].map(i=>'<button data-remove="'+i+'" aria-label="Remove '+resources[i].name+'">'+resources[i].name+' ×</button>').join(''):'Select resources to start a collection.';document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected.delete(Number(b.dataset.remove));render()});document.querySelector('#board-export').disabled=!selected.size}document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.pick);selected.has(i)?selected.delete(i):selected.add(i);render()});document.querySelector('#board-clear').onclick=()=>{selected.clear();render()};document.querySelector('#board-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({name:'NOIR reference collection',resources:[...selected].map(i=>resources[i])},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='noir-collection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};render();`),
make('ref-grouped-link-index','Grouped link index','An expandable reference index with section-level controls, resource search, and useful empty states.',
`<div class="ref"><div class="panel pad"><div class="row between"><strong>Reference shelf</strong><button class="btn" id="index-expand">Expand all</button></div><input class="link-search" id="link-search" aria-label="Search reference shelf" placeholder="Filter references"><div id="link-groups"></div><p class="small muted" id="link-selected" role="status">Choose a reference to see its destination.</p></div></div>`,
`.link-search{width:100%;margin:14px 0 7px}.link-group{border-top:1px solid #303030;padding:9px 0}.link-group summary{cursor:pointer;color:#ccc;font-size:11px;list-style-position:inside}.link-group summary small{float:right;color:#777;font-size:9px}.link-group button{width:100%;display:flex;align-items:center;justify-content:space-between;padding:8px 0 3px 16px;color:#999;border:0;background:none;font-size:10px;text-align:left}.link-group button:hover{color:#eee}#link-selected{min-height:29px;padding-top:8px;overflow-wrap:anywhere}`,
`const groups=[{title:'Build an interface',items:[['shadcn/ui','https://ui.shadcn.com/'],['Radix UI','https://www.radix-ui.com/']]},{title:'Explain an interaction',items:[['Colorfigures','https://april-zhu.com/colorfigures'],['Tinycharts','https://april-zhu.com/tinycharts']]},{title:'Find a reference',items:[['Designeer','https://designeer.xyz/']]}];let expanded=false;function render(){const q=document.querySelector('#link-search').value.toLowerCase();const visible=groups.map(g=>({...g,items:g.items.filter(x=>(g.title+' '+x[0]).toLowerCase().includes(q))})).filter(g=>g.items.length);document.querySelector('#link-groups').innerHTML=visible.map(g=>'<details class="link-group" '+(expanded||q?'open':'')+'><summary>'+g.title+'<small>'+g.items.length+'</small></summary>'+g.items.map(x=>'<button data-url="'+x[1]+'">'+x[0]+' <span>↗</span></button>').join('')+'</details>').join('')||'<p class="muted small pad">No references match that filter.</p>';document.querySelectorAll('[data-url]').forEach(b=>b.onclick=()=>{const url=b.dataset.url;document.querySelector('#link-selected').innerHTML='<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+url+' ↗</a>'})}document.querySelector('#link-search').oninput=render;document.querySelector('#index-expand').onclick=()=>{expanded=!expanded;document.querySelector('#index-expand').textContent=expanded?'Collapse all':'Expand all';render()};render();`)
];
